theorem card_erase_topology [DecidableEq α] {U : Finset α} {s : α}
    (hU : U.card = 3) (hs : s ∈ U) :
    (U.erase s).card = 2

theorem card_common_wrong [DecidableEq α] {U : Finset α} {s t : α}
    (hU : U.card = 3) (hs : s ∈ U) (ht : t ∈ U) (hst : s ≠ t) :
    ((U.erase s) ∩ (U.erase t)).card = 1

theorem mem_validSplitsOn_isQuartetSplit (T : Tree.PhyloTree (Fin n))
    (q : Quartet n) {s : Circular.QuartetSplit (Fin n)}
    (hs : s ∈ T.validSplitsOn q.1 q.2) : Circular.IsQuartetSplit q.1 s

theorem isQuartetSplit_mem_validSplitsOn (T : Tree.PhyloTree (Fin n))
    (q : Quartet n) {s : Circular.QuartetSplit (Fin n)}
